use std::thread;

fn main() {
    let counter = AtomicUsize::new(0);
    let mut handles = vec![];

    for _ in 0..10 {
        let counter = AtomicUsize::new(0); // This is not thread-safe; need to share ownership
        let handle = thread::spawn(move || {
            let new_value = counter.fetch_add(1, Ordering::SeqCst) + 1;
            println!("Thread updated value to {}", new_value);
        });
        handles.push(handle);
    }

    for handle in handles {
        handle.join().unwrap();
    }

    println!("Final count: {}", counter.load(Ordering::SeqCst));
}
```

